// v222: how a look turns into parts and sheet bands (data/people.js), and that every look in the game names parts the
// sheet has (src/data/personSheet.js, generated by tools/sprites/person.py).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { lookOf, personLayers, HAIR_STYLES, BEARDS, OUTFITS } from '../src/data/people.js';
import { PERSON } from '../src/data/personSheet.js';
import { NPCS } from '../src/data/npcs.js';
import { CLOTHES } from '../src/data/clothing.js';

test('old looks keep their hair and beard', () => {
  assert.equal(lookOf({ long: true }).hair, 'long');
  assert.equal(lookOf({}).hair, 'short');
  assert.equal(lookOf({ beard: true }).beard, 'full');
  assert.equal(lookOf({ beard: false }).beard, null);
  assert.equal(lookOf({ hat: '#fff' }).hat, 'straw');   // a hat without a shape was always the straw hat
});

test('a style the sheet does not have falls back instead of drawing nothing', () => {
  const L = lookOf({ hairStyle: 'mohawk', beard: 'braids', outfit: 'armour', hat: '#fff', hatStyle: 'crown' });
  assert.deepEqual(L, { hair: 'short', beard: null, outfit: null, extra: null, hat: 'straw' });
});

test('under a hat the hair is the trimmed version, and the hat is drawn last', () => {
  const bands = personLayers({ skin: '#fff', hair: '#000', shirt: '#f00', pants: '#00f', hat: '#0f0', band: '#ff0', hatStyle: 'top' }).map(([b]) => b);
  assert.ok(bands.includes('hair:short@hat|hair'));
  assert.ok(!bands.includes('hair:short|hair'));
  assert.equal(bands[0], 'body|skin');
  assert.ok(bands.at(-1).startsWith('hat:top|'));
});

test('every layer a look draws is on the sheet and tinted to a colour', () => {
  const p = { skin: '#fff', hair: '#000', shirt: '#f00', pants: '#00f', hairStyle: 'bun', beard: 'goatee', outfit: 'apron', glasses: true, hat: '#0f0', hatStyle: 'beanie' };
  for (const [band, col] of personLayers(p)) {
    assert.ok(PERSON.layers.includes(band), band);
    if (!band.endsWith('|ink')) assert.ok(col, `${band} has a colour`);
  }
});

test('every labelled style is drawn on the sheet, and every drawn style is labelled', () => {
  assert.deepEqual(Object.keys(HAIR_STYLES).sort(), [...PERSON.styles.hair].sort());
  assert.deepEqual(Object.keys(BEARDS).sort(), [...PERSON.styles.beard].sort());
  assert.deepEqual(Object.keys(OUTFITS).sort(), [...PERSON.styles.outfit].sort());
});

test('every neighbour and every hat in the game uses styles the sheet has', () => {
  for (const n of NPCS) {
    const p = n.pal, L = lookOf(p);
    if (p.hairStyle) assert.equal(L.hair, p.hairStyle, n.id);
    if (p.outfit) assert.equal(L.outfit, p.outfit, n.id);
    if (typeof p.beard === 'string') assert.equal(L.beard, p.beard, n.id);
  }
  for (const [k, c] of Object.entries(CLOTHES)) if (c.slot === 'hat') assert.ok(PERSON.styles.hat.includes(c.style), k);
});
